-- The Palate: one row of prose, which may be empty.
--
-- Generated by `drizzle-kit generate` from `db/schema.ts`, then finished by hand with the
-- one row, the comments and the triggers that keep it there. Its id is `palate` and never a
-- `gen_prefixed_id()`: there is no second Palate for an id to tell it apart from.

CREATE TABLE "palate" (
	"id" text PRIMARY KEY DEFAULT 'palate' NOT NULL,
	"prose" text DEFAULT '' NOT NULL,
	"updated_at" timestamp with time zone,
	CONSTRAINT "palate_is_the_only_one" CHECK ("palate"."id" = 'palate')
);

--> statement-breakpoint
insert into palate (id, prose) values ('palate', '');
--> statement-breakpoint
comment on table palate is
  'The owner''s taste, in prose: what they like, what they do not, what they are curious about, what they want to spend. An instruction to the external sommelier. Exactly one row.';
--> statement-breakpoint
comment on column palate.prose is
  'Readable and writable over MCP. Empty until the owner or the assistant writes it.';
--> statement-breakpoint

-- **There is one Palate.** The check on the id makes a second row impossible; this makes
-- the first one permanent. Emptying it is writing '' into it, which is allowed.
create function there_is_one_palate() returns trigger
language plpgsql
as $$
begin
  raise exception 'there is one Palate, and it is written rather than removed'
    using errcode = 'restrict_violation',
          constraint = 'palate_is_never_removed';
end;
$$;
--> statement-breakpoint
comment on function there_is_one_palate() is
  'The one Palate row is never deleted or truncated; it is emptied by writing an empty prose.';
--> statement-breakpoint
create trigger palate_is_never_removed
  before delete on palate
  for each row execute function there_is_one_palate();
--> statement-breakpoint
create trigger palate_is_never_truncated
  before truncate on palate
  for each statement execute function there_is_one_palate();
